import { Box, Button, Container, Stack, Typography } from "@mui/material";
import masterData from "../../data/masterData.json";
import { ArrowForwardIcon, getIcon } from "../../utils/iconMap";
import { scrollToTop as lenisScrollToTop } from "../LenisSmoothScroll";

interface FooterCtaSectionProps {
  onTalkToExpert?: () => void;
}

export default function FooterCtaSection({ onTalkToExpert }: FooterCtaSectionProps) {
  const { footerCta } = masterData;

  const handleTalkToExpert = () => {
    if (onTalkToExpert) {
      onTalkToExpert();
      return;
    }
    lenisScrollToTop(false);
  };

  return (
    <Box
      sx={{
        position: "relative",
        overflow: "hidden",
        background: "linear-gradient(100deg, #002B6B 0%, #0056D2 55%, #1A6FE8 100%)",
        py: { xs: 5, md: 5.5 },
      }}
    >
      <Box
        sx={{
          position: "absolute",
          left: 0,
          top: 0,
          bottom: 0,
          width: { xs: "0%", md: "28%" },
          backgroundImage: `url(${footerCta.image})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          opacity: 0.45,
          maskImage: "linear-gradient(to right, #000 40%, transparent 100%)",
          WebkitMaskImage: "linear-gradient(to right, #000 40%, transparent 100%)",
        }}
      />
      <Box
        sx={{
          position: "absolute",
          width: 340,
          height: 340,
          borderRadius: "50%",
          border: "48px solid rgba(255,255,255,0.05)",
          right: -100,
          top: -120,
        }}
      />

      <Container maxWidth="lg" sx={{ position: "relative", zIndex: 1 }}>
        <Stack
          direction={{ xs: "column", md: "row" }}
          spacing={3}
          alignItems={{ xs: "flex-start", md: "center" }}
          justifyContent="space-between"
          sx={{ pl: { md: "22%" } }}
        >
          <Box sx={{ flex: 1 }}>
            <Typography
              sx={{
                color: "#fff",
                fontWeight: 800,
                fontSize: { xs: "1.2rem", md: "1.65rem" },
                letterSpacing: "0.02em",
                mb: 0.5,
              }}
            >
              {footerCta.headline}
            </Typography>
            <Typography sx={{ color: "rgba(255,255,255,0.92)", fontSize: { xs: 14.5, md: 17 } }}>
              {footerCta.subheadline}
            </Typography>
          </Box>

          <Button
            variant="contained"
            endIcon={<ArrowForwardIcon />}
            onClick={handleTalkToExpert}
            sx={{
              bgcolor: "#fff",
              color: "#0056D2",
              px: 3.25,
              py: 1.35,
              borderRadius: "999px",
              fontWeight: 700,
              fontSize: 14.5,
              "&:hover": { bgcolor: "#F0F6FF" },
              whiteSpace: "nowrap",
              flexShrink: 0,
            }}
          >
            {footerCta.buttonLabel}
          </Button>
        </Stack>

        <Stack
          direction="row"
          spacing={{ xs: 3, md: 5 }}
          justifyContent={{ xs: "flex-start", md: "flex-end" }}
          sx={{
            mt: 3.5,
            pt: 2.5,
            borderTop: "1px solid rgba(255,255,255,0.18)",
            pl: { md: "22%" },
          }}
        >
          {footerCta.trustPoints.map((point) => {
            const Icon = getIcon(point.icon);
            return (
              <Stack key={point.id} direction="row" spacing={1} alignItems="center">
                <Icon sx={{ color: "#fff", fontSize: 20 }} />
                <Typography sx={{ color: "#fff", fontSize: 12.5, fontWeight: 500 }}>
                  {point.label}
                </Typography>
              </Stack>
            );
          })}
        </Stack>
      </Container>
    </Box>
  );
}
